<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{api}from'../api';import type{Post}from'../types';const posts=ref<Post[]>([]);onMounted(async()=>posts.value=await api('/archive'));const groups=computed(()=>posts.value.reduce<Record<string,Post[]>>((all,p)=>{const key=(p.publishedAt||'').slice(0,7);(all[key]??=[]).push(p);return all},{}))</script><template><section class="page-head"><p class="eyebrow">/ ARCHIVE</p><h1>归档</h1></section><section class="archive" v-for="(items,month) in groups" :key="month"><h2>{{month}}</h2><RouterLink v-for="p in items" :key="p.id" :to="`/posts/${p.slug}`"><time>{{p.publishedAt?.slice(8,10)}}</time>{{p.title}}</RouterLink></section></template>
